pm.test('Booking ID search returns HTTP 200', function () {
    pm.response.to.have.status(200);
});

pm.test('Response is an array of positive integer booking IDs', function () {
    const bookings = pm.response.json();

    pm.expect(bookings).to.be.an('array');

    bookings.forEach(function (booking) {
        pm.expect(Number.isInteger(booking.bookingid)).to.equal(true);
        pm.expect(booking.bookingid).to.be.above(0);
    });
});

pm.test('Booking IDs are unique within this response', function () {
    const bookings = pm.response.json();
    const ids = bookings.map(function (booking) {
        return booking.bookingid;
    });

    pm.expect(new Set(ids).size).to.equal(ids.length);
});

pm.test('Results include the booking created by this workflow', function () {
    const ownBookingId = Number(
        pm.collectionVariables.get('bookingId')
    );

    pm.expect(
        Number.isInteger(ownBookingId) && ownBookingId > 0,
        'Run Create Booking successfully before these searches'
    ).to.equal(true);

    const bookings = pm.response.json();
    const ids = bookings.map(function (booking) {
        return booking.bookingid;
    });

    pm.expect(ids).to.include(ownBookingId);
});
